import{_ as a,c as t,o as i,ae as r}from"./chunks/framework.DI6M9D4h.js";const m=JSON.parse('{"title":"Plaid-Pad","description":"","frontmatter":{},"headers":[],"relativePath":"build-guides/plaid-pad/README.md","filePath":"build-guides/plaid-pad/README.md","lastUpdated":1767696877000}'),s={name:"build-guides/plaid-pad/README.md"};function l(o,e,n,h,p,d){return i(),t("div",null,[...e[0]||(e[0]=[r(`<h1 id="plaid-pad" tabindex="-1">Plaid-Pad <a class="header-anchor" href="#plaid-pad" aria-label="Permalink to &quot;Plaid-Pad&quot;">​</a></h1><img src="https://i.imgur.com/KHPId3G.jpg" width="400"><p>A 4x4 numpad/macro pad with only through hole components. It supports up to 4 rotary encoder. The positions for the encoder are interchangeable with keyboard switches.</p><hr><ul><li><a href="./buildguide_en.html"><strong>Build guide</strong></a></li><li><a href="#qmk-firmware">QMK Firmware</a></li><li><a href="#bootloader">Bootloader</a></li><li><a href="#changelog">Changelog</a></li><li><a href="./3d-print.html">3D printing parts</a> (simple case)</li><li><a href="./lasercut.html">Laser cut drawings</a> (guard plate, dampening foam)</li></ul><hr><h2 id="keymap" tabindex="-1">Keymap <a class="header-anchor" href="#keymap" aria-label="Permalink to &quot;Keymap&quot;">​</a></h2><img src="https://i.imgur.com/V82cMqq.png" width="400"><p>Below you can see the possible positions for the 4 rotary encoder (Rev1 only 2).<br><em>If you place a encoder in the top left corner (E1), you can&#39;t use another encoder in the lower right corner.</em></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Rev2                      Rev1</span></span>
<span class="line"><span>,-----------------------,   ,-----------------------,</span></span>
<span class="line"><span>|  E1 |  E2 |  E3 |  E4 |   |  E1 |     |     |  E2 |</span></span>
<span class="line"><span>|-----+-----+-----+-----|   |-----+-----+-----+-----|</span></span>
<span class="line"><span>|     |     |     |  E3 |   |     |     |     |     |</span></span>
<span class="line"><span>|-----+-----+-----+-----|   |-----+-----+-----+-----|</span></span>
<span class="line"><span>|     |     |     |  E2 |   |     |     |     |     |</span></span>
<span class="line"><span>|-----+-----+-----+-----|   |-----+-----+-----+-----|</span></span>
<span class="line"><span>|     |     |     |  E1 |   |     |     |     |     |</span></span>
<span class="line"><span>\`-----------------------&#39;   \`-----------------------&#39;</span></span></code></pre></div><ul><li>Encoder E1 performs a tap on KC_F17 and KC_F18</li><li>Encoder E2 performs a tap on KC_F19 and KC_F20</li><li>Encoder E3 performs a tap on KC_F21 and KC_F22</li><li>Encoder E4 performs a tap on KC_F23 and KC_F24</li></ul><p>The F17-F24 keys are intended to be customized via <a href="https://github.com/pqrs-org/Karabiner-Elements" target="_blank" rel="noreferrer">Karabiner-Elements</a> (OSX), or <a href="https://github.com/Lexikos/AutoHotkey_L" target="_blank" rel="noreferrer">AutoHotkey</a> (WIN).</p><p>It&#39;s a great companion to the Plaid keyboard by <a href="https://github.com/hsgw/" target="_blank" rel="noreferrer">hsgw</a> and heavily inspired by it.</p><ul><li>Keyboard Maintainer: BenRoe <a href="https://github.com/BenRoe" target="_blank" rel="noreferrer">Github</a> / <a href="https://twitter.com/keycapsss" target="_blank" rel="noreferrer">Twitter</a></li><li>Hardware Supported: ATmega328P with VUSB (<a href="#bootloader">see Bootloader section</a>)</li><li>Hardware Availability: <a href="https://keycapsss.com" target="_blank" rel="noreferrer">Keycapsss.com</a></li></ul><h2 id="qmk-firmware" tabindex="-1">QMK Firmware <a class="header-anchor" href="#qmk-firmware" aria-label="Permalink to &quot;QMK Firmware&quot;">​</a></h2><p><em>Bootloader (<a href="https://github.com/baerwolf/USBaspLoader" target="_blank" rel="noreferrer">USBaspLoader</a>) and Firmware (<a href="https://github.com/qmk/qmk_firmware/tree/master/keyboards/keycapsss/plaid_pad" target="_blank" rel="noreferrer">via keymap</a>) are already on the ATmega328P chip.</em></p><h3 id="qmk-with-vial-support-support-for-rotary-encoder" tabindex="-1">QMK with VIAL support (support for rotary encoder) <a class="header-anchor" href="#qmk-with-vial-support-support-for-rotary-encoder" aria-label="Permalink to &quot;QMK with VIAL support (support for rotary encoder)&quot;">​</a></h3><p><em>Plaid-Pad Kit&#39;s Rev3 shipped with preflashed VIAL firmware.</em> _If you have a Rev2 Plaid-Pad, or want to re-flash the VIAL firmware again, you can find a compiled firmware file here (<a href="./[keycapsss_plaid_pad_rev2_vial.hex](https://minhaskamal.github.io/DownGit/#/home?url=https://github.com/Keycapsss/Plaid-Pad/blob/master/keycapsss_plaid_pad_rev2_vial.hex)">Rev2</a>, <a href="./[keycapsss_plaid_pad_rev3_vial.hex](https://minhaskamal.github.io/DownGit/#/home?url=https://github.com/Keycapsss/Plaid-Pad/blob/master/keycapsss_plaid_pad_rev3_vial.hex)">Rev3</a>)</p><ol><li>Flash pre-compiled firmware on the Plaid-Pad with <a href="https://github.com/qmk/qmk_toolbox/releases" target="_blank" rel="noreferrer">QMK Toolbox</a> (<a href="#enter-bootloader-mode-to-flash-a-new-firmware">How to enter Bootloader Mode</a>).</li><li>Download the VIAL software from <a href="https://get.vial.today" target="_blank" rel="noreferrer">here</a></li><li>Connect the Plaid-Pad to the computer with a USB cable (Reconnect after flashing the firmware)</li><li>Open VIAL and change the keymap to your needs (automatic save)</li></ol><h3 id="qmk-with-via-support-no-rotary-encoder-support" tabindex="-1">QMK with VIA support (no rotary encoder support) <a class="header-anchor" href="#qmk-with-via-support-no-rotary-encoder-support" aria-label="Permalink to &quot;QMK with VIA support (no rotary encoder support)&quot;">​</a></h3><p><em>Plaid-Pad Kit&#39;s shipped before 11.09.2020 are flashed with the QMK Default Keymap.</em><em>To use VIA, compile the VIA Keymap with the following command and flash it with <a href="https://github.com/qmk/qmk_toolbox/releases" target="_blank" rel="noreferrer">QMK Toolbox</a> on the Plaid-Pad (<a href="#enter-bootloader-mode-to-flash-a-new-firmware">enter Bootloader Mode</a>).</em></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qmk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keycapsss/plaid_pad</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -km</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> via</span></span></code></pre></div><ol><li>Download the VIA software from <a href="https://github.com/the-via/releases/releases/latest" target="_blank" rel="noreferrer">here</a></li><li>Connect the Plaid-Pad to the computer with a USB cable</li><li>Open VIA, switch to the <code>CONFIGURE</code> tab and change the keymap to your needs (automatic save)</li></ol><p><em>The current VIA version can&#39;t change the rotary encoder function.</em></p><h3 id="qmk-default-keymap" tabindex="-1">QMK Default Keymap <a class="header-anchor" href="#qmk-default-keymap" aria-label="Permalink to &quot;QMK Default Keymap&quot;">​</a></h3><p>Make example for this keyboard (after <a href="https://docs.qmk.fm/#/getting_started_build_tools" target="_blank" rel="noreferrer">setting up your build environment</a>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keycapsss/plaid_pad:default</span></span></code></pre></div><p>or</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qmk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keycapsss/plaid_pad</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -km</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span></span></code></pre></div><p>Flashing example for this keyboard:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keycapsss/plaid_pad:default:flash</span></span></code></pre></div><p>or</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">qmk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> flash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -kb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keycapsss/plaid_pad</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -km</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span></span></code></pre></div><p>See the <a href="https://docs.qmk.fm/#/getting_started_build_tools" target="_blank" rel="noreferrer">build environment setup</a> and the <a href="https://docs.qmk.fm/#/getting_started_make_guide" target="_blank" rel="noreferrer">make instructions</a> for more information. Brand new to QMK? Start with the <a href="https://docs.qmk.fm/#/syllabus" target="_blank" rel="noreferrer">Complete Newbees Guide</a>.</p><p>You can find the rotary encoder code <a href="https://github.com/qmk/qmk_firmware/blob/95bbd799a4f86dac37fdf2354e008d2fed7f6660/keyboards/keycapsss/plaid_pad/keymaps/via/keymap.c#L71" target="_blank" rel="noreferrer">here</a>.</p><h2 id="bootloader" tabindex="-1">Bootloader <a class="header-anchor" href="#bootloader" aria-label="Permalink to &quot;Bootloader&quot;">​</a></h2><ul><li>same <code>usbasploader</code> as used for Plaid (<a href="https://github.com/hsgw/plaid/blob/master/doc/en/bootloader.md" target="_blank" rel="noreferrer">Instructions</a>, <a href="https://github.com/hsgw/USBaspLoader/tree/plaid" target="_blank" rel="noreferrer">Repository</a>)</li></ul><h3 id="enter-bootloader-mode-to-flash-a-new-firmware" tabindex="-1">Enter Bootloader Mode (to flash a new firmware) <a class="header-anchor" href="#enter-bootloader-mode-to-flash-a-new-firmware" aria-label="Permalink to &quot;Enter Bootloader Mode (to flash a new firmware)&quot;">​</a></h3><ul><li>Plug in the USB cable</li><li>Push and hold RESET switch</li><li>Push and hold BOOT switch</li><li>Release RESET switch</li><li>Release BOOT switch</li></ul><p>alternative method:</p><ul><li>Unplug the USB cable</li><li>Hold down the BOOT switch</li><li>Plug in the USB cable</li><li>Release the BOOT switch</li></ul><p>alternative method (<a href="https://docs.qmk.fm/#/feature_bootmagic?id=bootmagic-lite" target="_blank" rel="noreferrer">Bootmagic Lite</a>):</p><ul><li>Unplug the USB cable</li><li>Hold down the most top left key</li><li>Plug in the USB cable</li><li>Release the most top left key</li></ul><p>If you succeed to enter bootloader mode, you can see usbasp in device manager, or <code>*** USBAsp device connected</code> in <a href="https://github.com/qmk/qmk_toolbox" target="_blank" rel="noreferrer">QMK Toolbox</a>.</p><h2 id="changelog" tabindex="-1">CHANGELOG <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;CHANGELOG&quot;">​</a></h2><h3 id="rev1" tabindex="-1">Rev1 <a class="header-anchor" href="#rev1" aria-label="Permalink to &quot;Rev1&quot;">​</a></h3><ul><li>Initial pcb design</li><li>Optional up to 2 Rotary Encoder</li></ul><h3 id="rev2-rev1-1" tabindex="-1">Rev2 (Rev1.1) <a class="header-anchor" href="#rev2-rev1-1" aria-label="Permalink to &quot;Rev2 (Rev1.1)&quot;">​</a></h3><ul><li>Pcb&#39;s with the label Rev1.1 are Rev2 (fixed with the second ordered batch)</li><li>Optional: up to 4 Rotary Encoder</li><li>Support for 3pin switches with the new top plate</li><li>Add a small PLAID-PAD text beneath the USB-C connector</li></ul><h3 id="rev2-1" tabindex="-1">Rev2.1 <a class="header-anchor" href="#rev2-1" aria-label="Permalink to &quot;Rev2.1&quot;">​</a></h3><ul><li>Bigger solder pads for the USB-C connector</li><li>Support for Choc V2 switches <em>(issue that the keycap touch the mounting screw, if bottoming out)</em></li><li>Changed case mounting style <em>(spacer go through the pcb and screwed on the top and bottom plate)</em></li></ul><h3 id="rev3" tabindex="-1">Rev3 <a class="header-anchor" href="#rev3" aria-label="Permalink to &quot;Rev3&quot;">​</a></h3><ul><li>Support for a SSD1306 oled display (I2C Pins C4/C5)</li><li>Removed the 2 indicator LEDs (Pin C4/C5)</li><li>Added a power indicator LED</li><li>Changed case mounting style back to the previous style (spacer mounted between mid PCB and bottom plate) - fix ChocV2 issue from REV2.1</li></ul>`,53)])])}const u=a(s,[["render",l]]);export{m as __pageData,u as default};
